def gen(rng):
    def fmt(s):
        return str(len(s)) + ('\n' + s if s else '')

    ALNUM = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

    def rs(n, alpha):
        return ''.join(rng.choice(alpha) for _ in range(n))

    def runs(total, maxrun):
        out = []
        n = 0
        prev = ''
        while n < total:
            c = rng.choice(ALNUM)
            while c == prev:
                c = rng.choice(ALNUM)
            k = min(rng.randint(1, maxrun), total - n)
            out.append(c * k)
            n += k
            prev = c
        return ''.join(out)

    tests = [fmt(''), fmt('a'), fmt('aaaa'), fmt('ab'), fmt('aabbbcccdddd'), fmt('AaAAaaa'), fmt('abababab'),
             fmt('zzzaaa'), fmt('0011000'), fmt('aAaAaA')]
    for _ in range(40):
        n = rng.randint(1, 30)
        tests.append(fmt(rs(n, rng.choice(['a', 'ab', 'abc', 'aA', ALNUM]))))
    tests.append(fmt('a' * 1000000))
    tests.append(fmt(rs(1000000, 'ab')))
    tests.append(fmt(runs(1000000, 50000)))
    tests.append(fmt('ab' * 250000 + 'c' * 3 + 'd' * 499997))
    tests.append(fmt(rs(1000000, ALNUM)))
    return tests

